script:
/* The native post editor (write_*.js). Sizes were measured from the old page. */

#cafe-write {
  --w-outline: var(--outline-gray-1);
  --w-outline-2: var(--outline-gray-2);
  --w-surface: var(--surface-gray-2);
  --w-ink: var(--ink-gray-9);
  --w-ink-8: var(--ink-gray-7);
  --w-ink-5: var(--ink-gray-5);
  --w-ink-4: var(--ink-gray-4);
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  line-height: 1.15;
  color: var(--w-ink);
}
#cafe-write *,
#cafe-write *::before,
#cafe-write *::after {
  box-sizing: border-box;
}
#cafe-write [hidden],
.cafe-w-btn[hidden],
.cafe-w-more[hidden],
.cafe-w-menu [hidden] {
  display: none !important;
}
.cafe-w-icon {
  display: inline-flex;
  flex-shrink: 0;
}
.cafe-w-icon svg {
  width: 100%;
  height: 100%;
}
.cafe-w-small {
  width: 16px;
  height: 16px;
}
.cafe-w-large {
  width: 32px;
  height: 32px;
}

/* ---- Header buttons ---- */
.cafe-w-btn:hover:not(:disabled) {
  background: var(--surface-gray-1) !important;
}
.cafe-w-btn.cafe-btn-solid:hover:not(:disabled) {
  background: var(--surface-gray-9) !important;
}
.cafe-w-btn.busy {
  position: relative;
  cursor: default;
}
.cafe-w-btn.busy span {
  visibility: hidden;
}
.cafe-w-btn.busy::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 9999px;
  content: '';
  animation: cafe-w-spin 0.7s linear infinite;
}
@keyframes cafe-w-spin {
  to {
    transform: rotate(360deg);
  }
}
.cafe-w-more:hover {
  background: var(--surface-gray-3) !important;
}

/* ---- The page ---- */
.cafe-w-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.cafe-w-page {
  display: flex;
  flex-direction: column;
  /* Fills .cafe-w-scroll exactly when the post is short, so there's nothing
     to scroll to reach the tag bar; real content still grows past this and
     scrolls normally, since min-height (not height) only sets a floor. */
  min-height: 100%;
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 40px 0;
}
.cafe-w-form {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.cafe-w-loading {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  gap: 12px;
}
.cafe-w-loading .cafe-skeleton {
  height: 14px;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--w-surface), #fafafa, var(--w-surface));
  background-size: 200% 100%;
  animation: cafe-pulse 1.2s ease-in-out infinite;
}
.cafe-w-status {
  margin: 0;
  color: var(--w-ink-5);
  font-size: 13px;
  line-height: 14.95px;
  text-align: center;
}
.cafe-w-tool {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--ink-gray-8);
  font-size: 13px;
  cursor: pointer;
}
.cafe-w-tool:hover {
  background: var(--w-surface);
}
.cafe-w-tool.on,
.cafe-w-tool[aria-pressed='true'] {
  background: var(--outline-gray-2);
}
.cafe-w-sep {
  width: 1px;
  height: 20px;
  flex-shrink: 0;
}
.cafe-w-title {
  display: block;
  width: 100%;
  margin-top: 16px;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--w-ink);
  font: inherit;
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 0.005em;
  line-height: 33.6px;
}
.cafe-w-title::placeholder {
  color: var(--w-ink-4);
  opacity: 1;
}
.cafe-w-editor {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  margin-top: 16px;
  color: var(--w-ink-8);
}
.cafe-w-prose {
  flex: 1;
  outline: none;
  color: var(--ink-gray-8);
  font-size: 15px;
  line-height: 25.5px;
  letter-spacing: 0.02em;
}
.cafe-w-prose > * + * {
  margin-top: 16px;
}
.cafe-w-prose p {
  margin: 0;
}
.cafe-w-prose h1,
.cafe-w-prose h2,
.cafe-w-prose h3,
.cafe-w-prose h4 {
  margin-bottom: 0;
  color: var(--w-ink);
  font-weight: 600;
}
.cafe-w-prose > h1,
.cafe-w-prose > h2,
.cafe-w-prose > h3,
.cafe-w-prose > h4 {
  margin-top: 24px;
}
.cafe-w-prose > :first-child {
  margin-top: 0;
}
.cafe-w-prose > h1 + *,
.cafe-w-prose > h2 + *,
.cafe-w-prose > h3 + *,
.cafe-w-prose > h4 + * {
  margin-top: 8px;
}
.cafe-w-prose h1 { font-size: 25.7143px; line-height: 32px; }
.cafe-w-prose h2 { font-size: 19.2857px; line-height: 26.0357px; }
.cafe-w-prose h3 { font-size: 17.1429px; line-height: 24px; }
.cafe-w-prose h4 { font-size: 15px; line-height: 21px; }
.cafe-w-prose strong {
  font-weight: 600;
}
.cafe-w-prose p.is-editor-empty:first-child::before {
  float: left;
  height: 0;
  color: var(--w-ink-4);
  content: attr(data-placeholder);
  pointer-events: none;
}
.cafe-w-prose blockquote {
  margin-left: 0;
  padding-left: 15px;
  border-left: 2px solid #c2c2c2;
  color: var(--ink-gray-6);
  font-weight: 500;
}
.cafe-w-prose ul,
.cafe-w-prose ol {
  margin-bottom: 0;
  padding-left: 22.5px;
}
.cafe-w-prose ol {
  padding-left: 25.5px;
}
.cafe-w-prose li + li {
  margin-top: 4px;
}
.cafe-w-prose > ul + ol,
.cafe-w-prose > ol + ul,
.cafe-w-prose > ul + ul,
.cafe-w-prose > ol + ol {
  margin-top: 4px;
}
.cafe-w-prose ul li::marker {
  color: var(--ink-gray-3);
}
.cafe-w-prose ol li::marker {
  color: var(--ink-gray-4);
}
.cafe-w-prose li > p {
  margin: 0;
}
.cafe-w-prose ul {
  list-style: disc;
}
.cafe-w-prose ol {
  list-style: decimal;
}
.cafe-w-prose a {
  color: var(--w-ink);
  font-weight: 500;
  text-decoration: underline;
}
.cafe-w-prose mark {
  background: #ffe97a;
}

/* An image in the story: the same 16:9 crop the published post has.
   inline-block, not block: the node is schema-inline (so it can sit inside
   a paragraph's text at all), and `block` forced a line break before it even
   when nothing but ProseMirror's own invisible cursor-positioning markup
   preceded it - on an otherwise-empty line, that break rendered as a blank
   line above the image. inline-block still lays out full-width (explicit
   width here) without forcing that break; vertical-align keeps it from
   sitting on a text baseline, which would otherwise leave a few stray
   pixels of gap beneath it the way an inline image normally would. */
.cafe-w-image {
  display: inline-block;
  width: 100%;
  margin: 16px 0;
  vertical-align: top;
}
.cafe-w-image-box {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: 4px;
  background: var(--w-surface);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}
.cafe-w-image-box img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: grab;
}
.cafe-w-image-status {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.7);
  color: var(--w-ink-5);
  font-size: 13px;
}
.cafe-w-image-status:empty {
  display: none;
}
.cafe-w-image.failed .cafe-w-image-status {
  color: #b41d1d;
}
.cafe-w-image-menu-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  display: none;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.7);
  color: var(--ink-base);
  cursor: pointer;
}
.cafe-w-image:hover .cafe-w-image-menu-btn,
.cafe-w-image.menu-open .cafe-w-image-menu-btn {
  display: flex;
}
.cafe-w-image-menu {
  position: absolute;
  top: 40px;
  right: 8px;
  z-index: 5;
  display: none;
  min-width: 160px;
  padding: 4px;
  border-radius: 8px;
  background: var(--surface-base);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.08),
    0 8px 24px rgba(0, 0, 0, 0.12);
}
.cafe-w-image.menu-open .cafe-w-image-menu {
  display: block;
}
.cafe-w-image-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 32px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.cafe-w-image-menu-item:hover {
  background: var(--w-surface);
}
.cafe-w-image-menu-item.danger {
  color: #b41d1d;
}
.cafe-w-image-menu-item svg {
  flex-shrink: 0;
}
.cafe-w-caption {
  display: block;
  width: 100%;
  height: 28px;
  margin-top: 0;
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--w-ink-5);
  font: inherit;
  font-size: 14px;
  text-align: center;
}
.cafe-w-prose div[data-type='image-group'] {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 8px;
}
.cafe-w-prose div[data-type='image-group'] .cafe-w-image {
  margin: 0;
}

/* ---- Tags and errors ---- */
.cafe-w-tags {
  margin-top: 32px;
}
.cafe-w-tags label {
  display: block;
  margin-bottom: 6px;
  color: var(--w-ink-5);
  font-size: 14px;
}
/* Matches frappe-ui's own MultiEmailInput (the closest first-party
   pills-in-an-input component): box = rounded-4/bg-surface-gray-2, chip =
   rounded-4 bordered bg-surface-base (not a filled pill), remove icon =
   size-3 with no button chrome, panel = rounded-6/shadow-2xl, item rows =
   rounded-4 with a soft hover tint. */
.cafe-w-tag-box {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 28px;
  /* Extra right padding clears the toggle, which floats (see below) instead
     of sitting in the flex row — otherwise it ate into the row's width and
     forced the input onto its own near-empty second line well before the
     chips actually ran out of room. */
  padding: 4px 28px 4px 6px;
  border-radius: 8px;
  background: var(--w-surface);
  transition: box-shadow 0.15s ease;
}
.cafe-w-tag-box:focus-within {
  box-shadow: 0 0 0 2px rgba(15, 15, 15, 0.12);
}
.cafe-w-tag-fields {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.cafe-w-tag-chips {
  display: contents;
}
.cafe-w-tag-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 2px 2px 10px;
  border-radius: 9999px;
  background: var(--outline-gray-2);
  color: var(--ink-gray-8);
  font-size: 13px;
  white-space: nowrap;
}
.cafe-w-tag-x {
  position: relative;
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  border-radius: 9999px;
  background: none;
  color: var(--w-ink-5);
  cursor: pointer;
  touch-action: manipulation;
}
/* The visible icon is 18px, well under the ~24px a mouse/finger reliably
   hits on the first try — this pads the real clickable area out without
   changing how the button looks or affecting layout. */
.cafe-w-tag-x::before {
  position: absolute;
  inset: -6px;
  content: '';
}
.cafe-w-tag-x:hover {
  background: rgba(0, 0, 0, 0.08);
}
.cafe-w-tag-fields input {
  /* A plain flex-basis: auto falls back to the browser's own default text
     input width (~170px+) for the *wrap* decision, even though min-width
     clamps the final rendered size — so it got bumped to its own line
     whenever the chips didn't leave 170px free, well before the row was
     actually out of room. An explicit small basis fixes the wrap decision
     itself; flex-grow still lets it fill the line when there's space. */
  flex: 1 1 40px;
  min-width: 40px;
  padding: 2px;
  border: 0;
  outline: none;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
}
.cafe-w-tag-fields input::placeholder {
  color: var(--w-ink-4);
  opacity: 1;
}
.cafe-w-tag-toggle {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--w-ink-4);
  cursor: pointer;
}
.cafe-w-tag-toggle:hover {
  color: var(--w-ink-8);
}
.cafe-w-tag-toggle .cafe-w-icon {
  transition: transform 0.2s cubic-bezier(0.23, 1, 0.32, 1);
}
.cafe-w-tag-toggle.open .cafe-w-icon {
  transform: rotate(180deg);
}
.cafe-w-tag-results {
  position: absolute;
  bottom: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 5;
  max-height: 240px;
  overflow-y: auto;
  padding: 4px;
  border-radius: 10px;
  background: var(--surface-base);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.05),
    0 20px 40px -10px rgba(0, 0, 0, 0.25);
}
.cafe-w-tag-option {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 28px;
  padding: 6px 8px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.cafe-w-tag-option:hover {
  background: rgba(15, 15, 15, 0.045);
}

/* The "[[" search popup (write_editor.js's buildPostLinkSearch) - same
   floating-panel look as the tag dropdown above, positioned at the typed
   "[[" instead of anchored to a field. */
.cafe-w-link-search {
  position: fixed;
  z-index: 30;
  width: 280px;
  max-height: 280px;
  padding: 4px;
  border-radius: 10px;
  background: var(--surface-base);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.05),
    0 20px 40px -10px rgba(0, 0, 0, 0.25);
}
.cafe-w-link-search input {
  display: block;
  width: 100%;
  height: 32px;
  margin-bottom: 4px;
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  background: var(--w-surface);
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
  outline: none;
}
.cafe-w-link-results {
  max-height: 220px;
  overflow-y: auto;
}
.cafe-w-link-option {
  display: block;
  width: 100%;
  min-height: 32px;
  padding: 6px 8px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.cafe-w-link-option:hover {
  background: rgba(15, 15, 15, 0.045);
}
.cafe-w-link-empty {
  margin: 0;
  padding: 6px 8px;
  color: var(--w-ink-5);
  font-size: 13px;
}

/* The "@" mention popup (write_editor.js's buildMentionSearch) - same
   floating-panel look/size as the "[[" post-link popup above (280px,
   10px radius, same shadow), just without its own input: the query is
   typed live into the document, same as the chat composer's own mentions
   (.cafe-c-mention in chat.css, which this mirrors). */
.cafe-w-mentions {
  position: fixed;
  z-index: 30;
  width: 280px;
  max-height: 280px;
  overflow-y: auto;
  padding: 4px;
  border-radius: 10px;
  background: var(--surface-base);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.05),
    0 20px 40px -10px rgba(0, 0, 0, 0.25);
}
.cafe-w-mention-option {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 6px 8px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--w-ink-8);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.cafe-w-mention-option.on,
.cafe-w-mention-option:hover {
  background: rgba(15, 15, 15, 0.045);
}
.cafe-w-mention-name {
  overflow: hidden;
  color: var(--w-ink-5);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-w-mention-empty {
  margin: 0;
  padding: 6px 8px;
  color: var(--w-ink-5);
  font-size: 13px;
}
/* The mention itself, once inserted - plain bold text (Gameplan's own
   mention style), same as the chat composer's rendered mentions
   (.cafe-c-html .mention / .cafe-c-prose .mention in chat.css), shown
   here while writing. */
.cafe-w-prose .mention {
  font-weight: 600;
}

.cafe-w-error {
  margin: 12px 0 0;
  color: #b41d1d;
  font-size: 13px;
}

/* ---- Menus and the selection bar ---- */
.cafe-w-menu,
.cafe-w-bubble {
  position: fixed;
  z-index: 70;
  border-radius: 8px;
  background: var(--surface-base);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.08), 0 8px 24px rgba(0, 0, 0, 0.12);
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  color: var(--ink-gray-8);
}
.cafe-w-menu {
  min-width: 160px;
  padding: 4px;
}
.cafe-w-menu-item {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-w-menu-item:hover,
.cafe-w-menu-item.active {
  background: var(--surface-gray-2, var(--w-surface));
}
.cafe-w-menu-item.danger {
  color: #b41d1d;
}
.cafe-w-menu .cafe-w-icon {
  color: var(--w-ink-5);
}
.cafe-w-menu-item.danger .cafe-w-icon {
  color: inherit;
}
.cafe-w-bubble {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
}
.cafe-w-bubble[hidden] {
  display: none;
}
/* Medium's "+": floats to the left of an empty paragraph line. Size comes
   from .cafe-w-tool (28px, same as every other editor button); round, not
   that button's 8px radius, to read as Medium's own circular "+" rather
   than a toolbar tool. Colours are frappe-ui's subtle/gray Button variant
   exactly: bg-surface-gray-2 at rest, hover bg-surface-gray-3, active
   bg-surface-gray-4 - a tinted background, not transparent like the other
   tool buttons, since this one floats over plain page background and needs
   its own visible edge. */
.cafe-w-plus {
  position: fixed;
  z-index: 60;
  border-radius: 9999px;
  background: var(--surface-gray-2);
  color: var(--ink-gray-8);
}
.cafe-w-plus:hover {
  background: var(--surface-gray-3);
}
.cafe-w-plus:active {
  background: var(--surface-gray-4);
}
.cafe-w-plus[hidden] {
  display: none;
}

/* ---- Story preview ----
   Everything below renders inside a CAFE.dialog, which appends to
   document.body - outside #cafe-write's own subtree, where this file's
   --w-outline/--w-ink-* aliases (defined at the top of this file, scoped to
   #cafe-write) aren't inherited and silently resolve to nothing (an invalid
   var() drops the whole declaration, not just that one value - a
   `border-top: 1px solid var(--w-outline)` using them doesn't draw ANY
   border, not just a transparent one). Use the real global tokens
   (--outline-gray-1, --ink-gray-5, etc., from styles.css's :root) directly
   in this section instead - that bit everyone's missed here before. */
.cafe-dialog.cafe-w-story-dialog {
  max-width: 820px;
  /* A bit more room under the actions than the default dialog's 28px —
     this one opens with a big cover image up top, so it wants more
     breathing room at the bottom to balance. */
  padding-bottom: 36px;
}
/* The crop-adjust view (startAdjust/drawAdjust) is just one image frame,
   no second column - the wide layout above is for the title/excerpt/tags
   + live preview view only. */
.cafe-dialog.cafe-w-story-dialog.cafe-w-adjusting {
  max-width: 576px;
}
/* Two columns: the editable fields (cover/title/excerpt/tags) on the left,
   a live read-only mock of the feed row this becomes on the right - an even
   split, not the fields column crowding out the preview. Same grid for the
   whole dialog body, so the crop-adjust view (which replaces body's
   children directly, bypassing .cafe-w-story-main/-side) can just span
   both columns below instead of being forced into a 2-up layout meant for
   the main view. */
.cafe-w-story {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: start;
}
.cafe-w-story > .cafe-w-adjust-hint,
.cafe-w-story > .cafe-w-frame {
  grid-column: 1 / -1;
}
.cafe-w-story-main {
  min-width: 0;
}
.cafe-w-story-side {
  min-width: 0;
  /* Lines up with .cafe-w-cover's own 16px top margin, so both columns'
     first real content starts at the same height. */
  margin-top: 16px;
}
/* Sits next to the dialog's own "Story Preview" <h2> (see W.openPreview's
   title-row wrapping) - same type as that heading, not a small caption
   above the card anymore. Same grid (columns + gap, and no padding of its
   own - padding would shrink this grid's own available width relative to
   .cafe-w-story's below it, throwing the two columns out of alignment)
   as .cafe-w-story itself, so the label lines up exactly over the card's
   own left edge. */
.cafe-w-story-title-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: baseline;
  gap: 24px;
}
.cafe-w-story-title-row h2 {
  padding-right: 0;
}
.cafe-w-story-side-label {
  /* The close button sits over this column, not the h2's - its own
     padding here clears it without affecting the grid's own track sizing
     the way padding on the grid container itself would. */
  padding-right: 40px;
  font-size: 18px;
  font-weight: 600;
  line-height: 24px;
  color: var(--ink-gray-9);
}
/* A small, read-only mock of the home feed's own row (home_page.py's
   build_feed_row) - same pieces playing the same roles, scaled down to fit
   the side panel: avatar+name, title, excerpt, cover thumbnail. Pixel values
   below mirror that file's NAME_STYLES/TITLE_STYLES/EXCERPT_STYLES/
   META_STYLES - kept in sync by hand, there's no shared source between a
   Builder data script and this vendor JS. */
.cafe-w-story-card {
  padding: 12px;
  border: 1px solid var(--outline-gray-1);
  border-radius: 10px;
}
.cafe-w-story-card-author {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 420;
  letter-spacing: 0.02em;
  line-height: 1.15;
  color: var(--ink-gray-8);
}
.cafe-w-story-card-avatar {
  width: 20px;
  height: 20px;
  font-size: 13px;
}
.cafe-w-story-card-body {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-top: 10px;
}
.cafe-w-story-card-text {
  flex: 1 1 0%;
  min-width: 0;
}
.cafe-w-story-card-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--ink-gray-8);
  letter-spacing: 0.015em;
  line-height: 1.15;
  overflow-wrap: break-word;
}
.cafe-w-story-card-excerpt {
  margin: 4px 0 0;
  color: var(--ink-gray-6);
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  line-height: 1.5;
}
.cafe-w-story-card-thumb {
  width: 96px;
  height: 72px;
  flex-shrink: 0;
  border-radius: 10px;
  background: var(--surface-gray-2);
  object-fit: cover;
}
.cafe-w-story-card-meta {
  margin: 10px 0 0;
  color: var(--ink-gray-5);
  font-size: 12px;
  font-weight: 420;
  letter-spacing: 0.02em;
  line-height: 1.15;
}
/* The nested "Schedule for later" dialog (same copy/shape as Gameplan's own
   ScheduleDialog.vue) - vanilla-JS rebuilds of frappe-ui's DatePicker/
   TimePicker (see write_preview.js's own comment on what's deliberately
   left out), styled to match: same trigger-button shape, same popover
   panel (white, rounded, shadowed), same colors
   (bg-surface-gray-9/text-ink-base for a selected day or time, exactly
   frappe-ui's CalendarPanel.vue/TimePicker.vue values). */
.cafe-w-schedule-hint {
  margin: 0 0 12px;
  color: var(--ink-gray-6);
  font-size: 14px;
  line-height: 1.5;
}
.cafe-w-schedule-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
}
.cafe-w-picker-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--outline-gray-1);
  border-radius: 8px;
  outline: none;
  background: transparent;
  font: inherit;
  color: var(--ink-gray-8);
  cursor: pointer;
}
.cafe-w-schedule-time {
  width: auto;
}
.cafe-w-picker-value {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
/* Both popovers (calendar + time list) - position set inline (next to
   whichever trigger opened it), appended to body so a dialog's own
   overflow/stacking can't clip them. */
.cafe-w-picker-panel {
  position: fixed;
  z-index: 1100;
  border-radius: 10px;
  background: #ffffff;
  border: 1px solid var(--outline-gray-1);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
}
.cafe-w-cal-panel {
  width: 240px;
  padding: 8px;
}
.cafe-w-cal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
  padding: 0 0 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink-gray-7);
}
.cafe-w-cal-nav-group {
  display: flex;
  align-items: center;
}
.cafe-w-cal-nav,
.cafe-w-cal-today {
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  color: var(--ink-gray-7);
  cursor: pointer;
  border-radius: 6px;
}
.cafe-w-cal-nav {
  width: 24px;
  height: 24px;
}
.cafe-w-cal-today {
  height: 24px;
  padding: 0 6px;
  font-size: 11px;
}
.cafe-w-cal-nav:hover,
.cafe-w-cal-today:hover {
  background: var(--surface-gray-2);
}
.cafe-w-cal-weekdays {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-bottom: 2px;
  text-transform: uppercase;
  font-size: 11px;
  font-weight: 500;
  color: var(--ink-gray-4);
}
.cafe-w-cal-weekdays span {
  display: flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
}
.cafe-w-cal-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
}
.cafe-w-cal-day {
  display: flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--ink-gray-8);
  font-size: 13px;
  cursor: pointer;
}
.cafe-w-cal-day:hover {
  background: var(--surface-gray-2);
}
.cafe-w-cal-day.outside {
  color: var(--ink-gray-3);
}
.cafe-w-cal-day.today {
  font-weight: 600;
  color: var(--ink-gray-9);
}
.cafe-w-cal-day.selected,
.cafe-w-cal-day.selected.today {
  background: var(--surface-gray-9);
  color: var(--ink-base);
}
.cafe-w-cal-day.selected:hover {
  background: var(--surface-gray-9);
}
.cafe-w-cal-day.disabled {
  color: var(--ink-gray-3);
  opacity: 0.4;
  cursor: not-allowed;
}
.cafe-w-time-panel {
  width: 176px;
  max-height: 192px;
  padding: 4px;
  overflow-y: auto;
}
.cafe-w-time-option {
  display: flex;
  align-items: center;
  width: 100%;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--ink-gray-6);
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}
.cafe-w-time-option:hover {
  background: var(--surface-gray-2);
  color: var(--ink-gray-8);
}
.cafe-w-time-option.selected {
  background: var(--surface-gray-3);
  color: var(--ink-gray-8);
}
.cafe-w-cover {
  position: relative;
  /* The dialog title has margin: 0 and this is the body's first child, so
     without this the image sits flush against the title with no gap at
     all — every other dialog avoids this because its body starts with a
     <p>, which already gets 12px from .cafe-dialog p. */
  margin-top: 16px;
  width: 100%;
  aspect-ratio: 1.91;
  overflow: hidden;
  border-radius: 6px;
  background: var(--surface-gray-2, var(--w-surface));
}
.cafe-w-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cafe-w-cover-empty {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  color: var(--ink-gray-4);
}
.cafe-w-cover-over {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: rgba(0, 0, 0, 0);
  opacity: 0;
  transition: background 0.15s, opacity 0.15s;
}
.cafe-w-cover:hover .cafe-w-cover-over {
  background: rgba(0, 0, 0, 0.4);
  opacity: 1;
}
/* frappe-ui's own "subtle" gray button: bg-surface-gray-2, hover
   bg-surface-gray-3, text-ink-gray-8 — swapped in for the solid black
   pills these used to be. */
.cafe-w-cover-btn {
  padding: 6px 12px;
  border: 0;
  border-radius: 6px;
  background: var(--surface-gray-2);
  color: var(--ink-gray-8);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}
.cafe-w-cover-btn:hover {
  background: var(--surface-gray-3);
}
.cafe-w-read {
  margin: 8px 0 0;
  color: var(--ink-gray-5);
  font-size: 13px;
}
.cafe-w-story .cafe-field {
  margin: 12px 0 0;
  padding: 8px 0 0;
  border-top: 1px solid var(--outline-gray-1);
}
.cafe-w-story .cafe-field label {
  color: var(--ink-gray-6);
  font-size: 13px;
}
/* Tags used its own 32px top margin on the main editor page, where it was
   the first thing below the story; here it's one divider among several, so
   it takes the same 12px/8px/border-top rhythm as the publication picker
   and title/excerpt fields right above it. */
.cafe-w-story .cafe-w-tags {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid var(--outline-gray-1);
}
.cafe-w-story .cafe-w-tags label {
  color: var(--ink-gray-6);
  font-size: 13px;
}
.cafe-w-story-title,
.cafe-w-story-excerpt {
  display: block;
  width: 100%;
  margin: 8px 0 0;
  padding: 8px 0 0;
  border: 0;
  border-top: 1px solid var(--outline-gray-1);
  outline: none;
  background: transparent;
  font: inherit;
  resize: none;
}
.cafe-w-story-title {
  color: var(--ink-gray-8);
  font-size: 18px;
  font-weight: 600;
}
.cafe-w-story-excerpt {
  margin-top: 4px;
  color: var(--ink-gray-6);
  font-size: 13px;
  line-height: 1.5;
}
.cafe-w-story-title::placeholder,
.cafe-w-story-excerpt::placeholder {
  color: var(--ink-gray-4);
}
.cafe-w-story-note {
  margin: 8px 0 0;
  color: var(--ink-gray-4);
  font-size: 12px;
}
.cafe-w-adjust-hint {
  margin: 0 0 12px;
  color: var(--ink-gray-6);
  font-size: 13px;
}
.cafe-w-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 1.91;
  overflow: hidden;
  border-radius: 6px;
  background: #000;
  cursor: default;
  user-select: none;
  touch-action: none;
}
.cafe-w-frame.movable {
  cursor: move;
}

/* ---- Phone ---- */
@media (max-width: 767px) {
  .cafe-write-main {
    flex-grow: 0 !important;
    height: calc(100vh - 57px) !important;
  }
  /* 100vh is the mobile viewport with its address bar collapsed, taller
     than what's actually visible with the bar shown - this tracks the
     real, current visible height instead. */
  @supports (height: 100dvh) {
    .cafe-write-main {
      height: calc(100dvh - 57px) !important;
    }
  }
  .cafe-w-page {
    padding: 24px 16px;
  }
}
